const body = $json.body ?? $json;
const text = String(body.text ?? '').trim();
const parts = text.split('|').map((part) => part.trim());
const usage = 'Usage: /onboard-client Company | Contact Name | contact@email.com | Engagement | Amount | Owner Name | owner@email.com';
if (parts.length !== 7 || parts.some((part) => !part)) {
  return [{ json: { valid: false, slack_response: { response_type: 'ephemeral', text: `I could not create the onboarding. ${usage}` } } }];
}
const [companyName, contactName, contactEmail, dealName, rawAmount, ownerName, ownerEmail] = parts;
const amount = Number(rawAmount.replace(/[^0-9.-]/g, ''));
const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
if (!emailPattern.test(contactEmail) || !emailPattern.test(ownerEmail) || !Number.isFinite(amount) || amount < 0) {
  return [{ json: { valid: false, slack_response: { response_type: 'ephemeral', text: `Please provide valid contact and owner emails and a non-negative amount. ${usage}` } } }];
}
const stableKey = `${contactEmail}:${dealName}`.toLowerCase().replace(/[^a-z0-9@._:-]+/g, '-');
const sourceDealId = `slack:${body.team_id ?? 'workspace'}:${stableKey}`;
const normalized = {
  event_id: String(body.trigger_id ?? sourceDealId),
  source_deal_id: sourceDealId,
  company_name: companyName,
  primary_contact_name: contactName,
  primary_contact_email: contactEmail,
  deal_name: dealName,
  owner_name: ownerName,
  owner_email: ownerEmail,
  website: '',
  value_cents: Math.round(amount * 100),
  currency: 'USD',
  service_template_key: 'consulting-standard',
  closed_won_at: new Date().toISOString(),
  sla_hours: 72,
  source: 'slack',
  slack_user_id: String(body.user_id ?? ''),
  slack_channel_id: String(body.channel_id ?? '')
};
return [{ json: { valid: true, company_name: companyName, deal_name: dealName, payload_base64: Buffer.from(JSON.stringify(normalized)).toString('base64') } }];

const result = $json.result ?? {};
return [{ json: { slack_response: { response_type: 'ephemeral', text: `✅ Client onboarding created successfully.
*Status:* Received
*Onboarding ID:* ${result.onboarding_id ?? result.id ?? 'created'}
*Next:* Confirm the agreement and deposit, then provision the delivery workspace.` } } }];
